class Licznik {
  wartosc = 0; // pole klasy z wartoscia domyslna
  krok = 1;

  increment() {
    this.wartosc += this.krok;
    return this.wartosc;
  }
}

const licznik = new Licznik();
licznik.increment();
licznik.increment();
console.log(licznik.wartosc); // 2

