class PrzyciskV2 {
  wcisniety = 0;

  // arrow function jako pole klasy: this ZAWSZE wskazuje na instancje,
  // nawet gdy metoda jest wyrwana i przekazana jako callback
  onClick = () => {
    this.wcisniety++;
    console.log("klikniete:", this.wcisniety);
  };
}

const btn = new PrzyciskV2();
const handlerBezBind = btn.onClick; // wyrywamy metode
handlerBezBind(); // "klikniete: 1" - dziala poprawnie MIMO braku bind()!

